edit('FrameDeliveryBroker.swift', '    func post(_ frame: CompositedFrame) {\n        os_unfair_lock_lock(&lock)\n        guard !closed else { os_unfair_lock_unlock(&lock); return }\n        var retired: CompositedFrame?\n        if pending.count >= capacity { drops += 1; retired = pending.removeFirst() }\n        pending.append(frame)\n        let shouldSchedule = !isDraining\n        if shouldSchedule { isDraining = true }\n        os_unfair_lock_unlock(&lock)\n        withExtendedLifetime(retired) {}\n        if shouldSchedule { queue.async { self.drain() } }\n    }\n', '    func post(_ frame: CompositedFrame) {\n        let postStarted = CompositionHotPathProfile.stamp()\n        os_unfair_lock_lock(&lock)\n        let acquired = CompositionHotPathProfile.stamp()\n        guard !closed else { os_unfair_lock_unlock(&lock); return }\n        var retired: CompositedFrame?\n        if pending.count >= capacity { drops += 1; retired = pending.removeFirst() }\n        pending.append(frame)\n        let shouldSchedule = !isDraining\n        if shouldSchedule { isDraining = true }\n        let heldEnd = CompositionHotPathProfile.stamp()\n        os_unfair_lock_unlock(&lock)\n        let unlocked = CompositionHotPathProfile.stamp()\n        withExtendedLifetime(retired) {}\n        if shouldSchedule { queue.async { self.drain() } }\n        let end = CompositionHotPathProfile.stamp()\n        let p = CompositionHotPathProfile.shared\n        p.record("mailboxLockWait." + profileName, since: postStarted, until: acquired, sequence: frame.sequence)\n        p.record("mailboxLockHeld." + profileName, since: acquired, until: heldEnd, sequence: frame.sequence)\n        p.record("mailboxPostUnlock." + profileName, since: unlocked, until: end, sequence: frame.sequence)\n        p.record("mailboxPost." + profileName, since: postStarted, until: end, sequence: frame.sequence)\n    }\n')
edit('FrameDeliveryBroker.swift', '    private func drain() {\n        while true {\n            os_unfair_lock_lock(&lock)\n            guard !closed, !pending.isEmpty else {\n                isDraining = false; os_unfair_lock_unlock(&lock); return\n            }\n            let frame = pending.removeFirst()\n            os_unfair_lock_unlock(&lock)\n            sink(frame)\n        }\n    }\n', '    private func drain() {\n        var previousEnd: CompositionHotPathProfile.Stamp?\n        while true {\n            let started = CompositionHotPathProfile.stamp()\n            if let previousEnd { CompositionHotPathProfile.shared.record("mailboxBetweenCallbackResidual." + profileName, since: previousEnd, until: started) }\n            os_unfair_lock_lock(&lock)\n            guard !closed, !pending.isEmpty else {\n                isDraining = false; os_unfair_lock_unlock(&lock); return\n            }\n            let frame = pending.removeFirst()\n            os_unfair_lock_unlock(&lock)\n            let callback = CompositionHotPathProfile.stamp()\n            CompositionHotPathProfile.shared.record("mailboxDequeue." + profileName, since: started, until: callback, sequence: frame.sequence)\n            CompositionHotPathProfile.shared.point("mailboxDelivery." + profileName, sequence: frame.sequence)\n            let sinkStarted = CompositionHotPathProfile.stamp()\n            sink(frame)\n            let sinkEnd = CompositionHotPathProfile.stamp()\n            CompositionHotPathProfile.shared.record("mailboxSink." + profileName, since: sinkStarted, until: sinkEnd, sequence: frame.sequence)\n            previousEnd = CompositionHotPathProfile.stamp()\n        }\n    }\n')
